def polygon_area(points) -> float:
    area = 0
    n = len(points)
    for i in range(n):
        j = (i + 1) % n
        area += points[i][0] * points[j][1]
        area -= points[j][0] * points[i][1]
    return abs(area) / 2

def scanline(polygon):
    """Returns for each row, the min and max column inside the polygon"""
    min_max = {}
    for r in range(rows):
        entry_xs, exit_xs = [], []
        for i in range(len(polygon) - 1):
            p1, p2 = polygon[i], polygon[(i + 1) % len(polygon)]
            if p1[1] == p2[1]:  # horizontal edge, skip
                continue
            center_p = (r - p1[1]) / (p2[1] - p1[1])
            center_x = p1[0] + center_p * (p2[0] - p1[0])
            if p2[1] > p1[1]:
                entry_xs.append(center_x)
            else:
                exit_xs.append(-center_x)
        entry_xs.sort()
        exit_xs.sort(reverse=True)
        if not entry_xs or not exit_xs:
            continue
        for _ in range(len(entry_xs)):
            idx = exit_xs.index(max(x for x in entry_xs[:_]))
            min_max[r] = (int(entry_xs[_]), int(exit_xs[idx]))
    return min_max

