def convex_hull_by_angle(points):
    """Returns hull vertices sorted angularly around centroid"""
    points = sorted(list(set(points)))
    if len(points) <= 1:
        return points

    # Compute centroid
    centroid_r, centroid_c = sum(p[0] for p in points) / len(points), sum(p[1] for p in points) / len(points)

    # Sort by angle from centroid
    def angle_from_centroid(p):
        return math.atan2(p[1] - centroid_c, p[0] - centroid_r)  # (col, row)

    points_sorted = sorted(points, key=angle_from_centroid)

    return points_sorted

