        return False

    r_diff = br - ar
    c_diff = bc - ac

    is_num = (r_diff == 0) or (c_diff == 0) or (abs(r_diff) == abs(c_diff))
    if not is_num:
        return False

    # Check bounding box
    if not (min(ar, br) <= p[0] <= max(ar, br) and min(ac, bc) <= p[1] <= max(ac, bc)):
