                    filled.add((r, c))
    return filled

def points_on_aligned_segment_error(p1, p2):
    """Horizontal/vertical only (not 45° diagonals)."""
    r1, c1 = p1
    r2, c2 = p2
    pts = set()
    if r1 == r2:
        for c in range(min(c1, c2) + 1, max(c1, c2)):
            pts.add((r1, c))
    elif c1 == c2:
        for r in range(min(r1, r2) + 1, max(r1, r2)):
            pts.add((r, c1))
    return pts

def combined_fill(ones: Set[Tuple[int, int]]):
    """Combines horizontal/vertical segments with all rounded segment points."""
    filled = set()

    for a in ones:
        for b in ones:
            if a < b:
                r1, c1 = a
                r2, c2 = b
                dr = r2 - r1
                dc = c2 - c1

                # All rounded segment points
                for t in [0.25, 0.5, 0.75]:
                    r = round(r1 + t * dr)
                    c = round(c1 + t * dc)
                    filled.add((r, c))

    for a in ones:
        for b in ones:
            if a < b:
                filled.update(points_on_aligned_segment_error(a, b))

    return filled

